const $ = id => document.getElementById(id);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data={profiles:[],items:[],cutoff:''}, current={type:'home'}, selectedPost=null, editingItem=null, editingProfile=null, chosenDestination=null, filter='all', sourceData=null, sourceTimer=null, sourcePage=0, sourceSearch='', previewObserver=null;
let timerInfo={schedules:[],batch:null}, sourceCounts=new Map(), selectedSchedule=null, selectedScheduleRole='source', previewUrls=[], activeVideo=null;
let categoryRole='destination', editingCategory=null;
let navigationHistory=[{type:'home',value:null,categoryRole}], navigationIndex=0;
const platformLabel=p=>({tiktok:'TikTok',instagram:'Instagram',youtube:'YouTube',other:'Other'}[p]||p);
const profileById=id=>data.profiles.find(p=>p.id===Number(id));
const normalize=s=>String(s||'').replace(/^@/,'').toLowerCase();
const hasTag=(p,t)=>p.tags.some(x=>x.toLowerCase()===t.toLowerCase());
const safeUrl=s=>{try{let u=new URL(s);return ['http:','https:'].includes(u.protocol)?u.href:'';}catch{return '';}};
const person=()=>document.getElementById('user')?.value.trim()||localStorage.getItem('lifeinvader-name')||'';
function status(item,id){return item.statuses.find(s=>s.profile_id===Number(id));}
function sourceMatches(item,p){return p.role==='source'&&p.platform===item.platform&&normalize(p.name)===normalize(item.account);}
function allTags(role){const map=new Map();[...(data.categories||[]).filter(c=>c.role===role).map(c=>c.name),...data.profiles.filter(p=>p.role===role).flatMap(p=>p.tags)].forEach(t=>{if(!map.has(t.toLowerCase()))map.set(t.toLowerCase(),t);});return [...map.values()].sort((a,b)=>a.localeCompare(b));}
async function api(url, options){const r=await fetch(url,options);if(!r.ok)throw new Error(await r.text());return r.status===204?null:r.json();}
async function refresh(){try{data=await api('/api/items');render();if(current.type==='profile')loadProfileDownloads(current.value);await refreshTimers();}catch(e){$('notice').textContent=e.message;}}
function disposeGallery(){previewObserver?.disconnect();previewObserver=null;document.querySelectorAll('.source-video').forEach(v=>{v.pause();v.removeAttribute('src');v.load();});activeVideo=null;previewUrls.forEach(URL.revokeObjectURL);previewUrls=[];}
function showLocation(location){clearInterval(sourceTimer);sourceTimer=null;disposeGallery();sourceData=null;sourcePage=0;sourceSearch='';categoryRole=location.categoryRole;current={type:location.type,value:location.value};chosenDestination=null;filter='all';$('notice').textContent='';render();if(current.type==='source')loadSource(current.value);if(current.type==='profile')loadProfileDownloads(current.value);if(current.type==='sources'||current.type==='tag')loadSourceCounts();window.scrollTo(0,0);}
function go(type,value,role=categoryRole){const location={type,value:value??null,categoryRole:role},last=navigationHistory[navigationIndex];if(last.type!==location.type||last.value!==location.value||last.categoryRole!==location.categoryRole){navigationHistory=navigationHistory.slice(0,navigationIndex+1);navigationHistory.push(location);navigationIndex++;}showLocation(location);}
function moveHistory(delta){const next=navigationIndex+delta;if(next<0||next>=navigationHistory.length)return;navigationIndex=next;showLocation(navigationHistory[navigationIndex]);}
function avatar(p,large=false){const initial=esc((p.name||'?').replace(/^@/,'').slice(0,1).toUpperCase());const image=p.avatar_url?`<img src="${esc(p.avatar_url)}" alt="" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><b class="avatar-fallback" hidden>${initial}</b>`:initial;return `<div class="avatar ${esc(p.platform)} ${large?'large':''}">${image}<span>${esc(platformLabel(p.platform).slice(0,1))}</span></div>`;}
function profileCard(p){return `<button class="profile-card source-account" data-profile="${p.id}" data-ring="${p.id}">${avatar(p,true)}<strong>@${esc(p.name)}</strong><div class="profile-sub">${esc(platformLabel(p.platform))}</div><div class="timer-label" data-timer="${p.id}">Auto sync off</div><div class="profile-tags">${p.tags.slice(0,2).map(t=>`<span>${esc(t)}</span>`).join('')}</div></button>`;}
function sourceCard(p){const count=sourceCounts.get(p.id);return `<button class="profile-card source-account" data-profile="${p.id}" data-ring="${p.id}">${avatar(p,true)}<span class="source-new-count" data-new-count="${p.id}" hidden></span><strong>@${esc(p.name)}</strong><div class="profile-sub">${esc(platformLabel(p.platform))} · Source</div><div class="source-card-count" data-source-count="${p.id}">${count?.configured?`${count.videos} videos · ${count.photos} photos`:'Open source'}</div><div class="timer-label" data-timer="${p.id}">Auto sync off</div><div class="batch-label" data-batch-label="${p.id}"></div></button>`;}
function renderNav(){document.querySelector('[data-home]').classList.toggle('active',current.type==='home'||current.type==='profile');document.querySelector('[data-sources]').classList.toggle('active',current.type==='sources'||current.type==='source');document.querySelector('[data-categories]').classList.toggle('active',current.type==='categories'||current.type==='tag');}
function attachProfiles(){document.querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>{const p=profileById(b.dataset.profile);if(p)go(p.role==='source'?'source':'profile',p.id);});}
function renderHome(){const isSources=current.type==='sources';$('breadcrumb').innerHTML=isSources?'Sources':'Profiles';const p=data.profiles.filter(x=>x.role===(isSources?'source':'destination'));$('view').innerHTML=`<div class="simple-heading"><div><div class="eyebrow">${isSources?'CONTENT DISCOVERY':'YOUR SPACE'}</div><h1>${isSources?'Sources':'Profiles'}<span>.</span></h1></div><div class="heading-actions"><span class="total-count">${p.length} ${isSources?'sources':'profiles'}</span>${isSources?'<button class="button ghost" id="discover-sources">Find existing</button><button class="button outline" id="source-config">⚙ Source folders</button><button class="button primary" id="sync-all">↻ Sync all</button>':''}</div></div>${isSources?'<div id="batch-status" class="batch-status" hidden></div>':''}<div class="profiles-grid simple-grid">${p.map(isSources?sourceCard:profileCard).join('')}<button class="profile-card add-card" data-add><span>＋</span><strong>Add ${isSources?'source':'profile'}</strong></button></div>`;attachProfiles();updateTimerElements();document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>openProfile(null,'',isSources?'source':'destination'));if(isSources){$('source-config').onclick=openSourceSettings;$('discover-sources').onclick=discoverSources;$('sync-all').onclick=()=>syncAll(p);updateTimerElements();}}
function quickProfile(p){const n=data.items.filter(i=>status(i,p.id)?.state==='reported_posted').length;const c=sourceCounts.get(p.id);return `<button class="quick-profile" data-profile="${p.id}">${avatar(p)}<span class="quick-identity"><strong>@${esc(p.name)}</strong><small>${esc(platformLabel(p.platform))} · ${p.role==='source'?'Source':'Posting account'}</small></span><span class="quick-count" ${p.role==='source'?`data-source-count="${p.id}"`:''}>${p.role==='source'?(c?.configured?`${c.videos} videos`:'Download hub'):`${n} posts`}</span><span class="quick-arrow">↗</span></button>`;}
function renderCategories(){
  const tags=allTags(categoryRole),isSources=categoryRole==='source',label=isSources?'sources':'profiles';$('breadcrumb').innerHTML='Categories';
  $('view').innerHTML=`<div class="simple-heading"><div><div class="eyebrow">YOUR SPACE</div><h1>Categories<span>.</span></h1></div><button class="button primary" id="new-category">＋ New category</button></div><div class="category-tabs" role="tablist" aria-label="Category section"><button role="tab" aria-selected="${!isSources}" data-category-role="destination">Profiles</button><button role="tab" aria-selected="${isSources}" data-category-role="source">Sources</button></div><div class="category-section-heading"><div><h2>${isSources?'Source categories':'Profile categories'}</h2><p>Organize your ${label} into the groups you use.</p></div><span class="total-count">${tags.length} ${tags.length===1?'category':'categories'}</span></div><div class="category-grid">${tags.map(t=>{const members=data.profiles.filter(p=>p.role===categoryRole&&hasTag(p,t));return `<section class="category-card"><header><div><span class="category-icon">#</span><div><h2>${esc(t)}</h2><small>${members.length} ${isSources?(members.length===1?'source':'sources'):(members.length===1?'profile':'profiles')}</small></div></div><button class="category-open" data-tag="${esc(t)}">Dashboard ↗</button></header><div class="category-members">${members.map(quickProfile).join('')||`<p class="category-empty">No ${label} yet.</p>`}</div><div class="category-card-footer"><button class="category-manage" data-manage="${esc(t)}">＋ Manage ${label}</button></div></section>`;}).join('')}</div>${tags.length?'':`<div class="empty"><h3>No ${label} categories yet</h3><p>Create one to start organizing your ${label}.</p></div>`}`;
  document.querySelectorAll('[data-category-role]').forEach(b=>b.onclick=()=>go('categories',null,b.dataset.categoryRole));
  $('new-category').onclick=()=>{$('category-form').reset();$('category-dialog-description').textContent=`This category belongs to ${label}.`;$('category-error').textContent='';$('category-dialog').showModal();};
  attachProfiles();document.querySelectorAll('[data-tag]').forEach(b=>b.onclick=()=>go('tag',b.dataset.tag));document.querySelectorAll('[data-manage]').forEach(b=>b.onclick=()=>openMembers(b.dataset.manage,categoryRole));
  if(isSources)loadSourceCounts();
}
function openMembers(name,role){editingCategory={name,role};const accounts=data.profiles.filter(p=>p.role===role);$('members-title').textContent=name;$('members-description').textContent=`Choose the ${role==='source'?'sources':'profiles'} in this category.`;$('members-error').textContent='';$('members-list').innerHTML=accounts.length?accounts.map(p=>`<label class="discover-row"><input type="checkbox" value="${p.id}" ${hasTag(p,name)?'checked':''}>${avatar(p)}<span><strong>@${esc(p.name)}</strong><small>${esc(platformLabel(p.platform))}</small></span></label>`).join(''):`<p class="category-empty">Add a ${role==='source'?'source':'profile'} first.</p>`;$('members-dialog').showModal();}
$('category-form').onsubmit=async e=>{e.preventDefault();const name=$('category-name').value.trim();try{await api('/api/categories',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({role:categoryRole,name})});$('category-dialog').close();await refresh();openMembers(name,categoryRole);}catch(err){$('category-error').textContent=err.message;}};
$('members-form').onsubmit=async e=>{e.preventDefault();try{const ids=[...document.querySelectorAll('#members-list input:checked')].map(el=>Number(el.value));await api('/api/categories/members',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({role:editingCategory.role,name:editingCategory.name,profile_ids:ids})});$('members-dialog').close();await refresh();if(current.type==='tag'&&categoryRole==='source')loadSourceCounts();}catch(err){$('members-error').textContent=err.message;}};
function stats(profiles,items){const dests=profiles.filter(p=>p.role==='destination');const states=items.flatMap(i=>dests.map(p=>status(i,p.id)).filter(Boolean));return `<div class="dashboard-stats"><div><small>LIBRARY ITEMS</small><strong>${items.length}</strong><span>Available in this view</span></div><div><small>AVAILABLE</small><strong>${states.filter(s=>s.state==='available').length}</strong><span>Across posting accounts</span></div><div><small>CLAIMED</small><strong>${states.filter(s=>s.state==='claimed').length}</strong><span>Currently in progress</span></div><div><small>REPORTED POSTED</small><strong>${states.filter(s=>s.state==='reported_posted').length}</strong><span>Manually recorded</span></div></div>`;}
function renderDashboard(){const p=current.type==='profile'?profileById(current.value):null;if(current.type==='profile'&&!p){go('home');return;}const group=p?[p]:data.profiles.filter(x=>x.role===categoryRole&&hasTag(x,current.value));const dests=group.filter(x=>x.role==='destination');const sourceOnly=p?p.role==='source':categoryRole==='source';if(!p&&sourceOnly){renderSourceCategory(group);return;}const visibleItems=sourceOnly?data.items.filter(i=>group.some(x=>sourceMatches(i,x))):data.items;
if(!dests.some(x=>x.id===chosenDestination))chosenDestination=dests[0]?.id||null;
const name=p?'@'+p.name:current.value; $('breadcrumb').innerHTML=`<button data-crumb>${p?'Workspace':'Categories'}</button> <span>/</span> ${esc(name)}`;
const identity=p?`${avatar(p,true)}<div><div class="eyebrow">${esc(platformLabel(p.platform))} · ${p.role==='source'?'CONTENT SOURCE':'POSTING ACCOUNT'}</div><h1>@${esc(p.name)}<span>.</span></h1><p>Profile dashboard <span class="separator">•</span> ${p.tags.map(esc).join(' / ')||'No categories yet'}</p></div>`:`<div class="category-avatar">#</div><div><div class="eyebrow">CATEGORY DASHBOARD</div><h1>${esc(current.value)}<span>.</span></h1><p>${group.length} ${group.length===1?'profile':'profiles'} grouped in one place.</p></div>`;
const actions=p?`<button class="button outline" id="edit-profile">Edit profile</button><a class="button ghost" href="${esc(safeUrl(p.url))}" target="_blank" rel="noopener noreferrer">Open profile ↗</a>`:'<button class="button outline" id="manage-category">Manage profiles</button><button class="button outline" id="add-from-category">＋ Add profile</button>'; 
const groupStrip=!p?`<div class="section-heading group-heading"><div><div class="eyebrow">IN THIS CATEGORY</div><h2>Profiles</h2></div>${group.some(x=>x.role==='source')?'<button class="button outline" id="sync-category">↻ Sync sources</button>':''}</div><div class="profiles-grid compact">${group.map(x=>x.role==='source'?sourceCard(x):profileCard(x)).join('')}</div>`:'';
const destinations=dests.map(x=>`<option value="${x.id}" ${x.id===chosenDestination?'selected':''}>${esc(platformLabel(x.platform))} · @${esc(x.name)}</option>`).join('');
const toolbar=sourceOnly?'<p class="library-note">Showing imported content whose source platform and account name match these profiles.</p>':`<div class="toolbar"><label>Working as <input id="user" maxlength="80" placeholder="Your name" value="${esc(person())}"></label><label>Posting account <select id="destination" ${!dests.length?'disabled':''}>${destinations}</select></label><label>Period <select id="filter"><option value="all">All content</option><option value="before">Before launch</option><option value="after">At or after launch</option><option value="review">Needs date review</option></select></label><button id="pick" class="button dark" ${!dests.length?'disabled':''}>✳ Pick for me</button></div><p class="library-note">Shared library · Status is separate for each posting account. Cutoff: ${esc(data.cutoff)}. Date-only posts on launch day need review.</p>`;
$('view').innerHTML=`<div class="profile-hero"><div class="identity">${identity}</div><div class="hero-actions">${actions}</div></div>${p?'<section id="posting-queue"><p class="profile-loading">Loading queue…</p></section>':''}${p?'<section id="profile-analytics"><p class="profile-loading">Loading analytics…</p></section>':''}${stats(group,visibleItems)}${p?'<section id="profile-downloads"><p class="profile-loading">Loading your posts…</p></section>':''}${groupStrip}<div class="section-heading library-heading"><div><div class="eyebrow">${sourceOnly?'SOURCE CONTENT':'CONTENT & POSTING'}</div><h2>Content library</h2><p>${sourceOnly?'Posts imported from this source.':'Choose a post, claim it and record when it is published.'}</p></div><button class="button primary" id="show-import">＋ Add content</button></div>${toolbar}<div id="library-message" role="status"></div><div id="cards" class="cards"></div><div id="empty" class="empty" hidden><span>✳</span><h3>Nothing here yet.</h3><p>Add content or choose a different filter.</p></div>`;
document.querySelector('[data-crumb]').onclick=()=>go(p?'home':'categories');attachProfiles();if(p)$('edit-profile').onclick=()=>openProfile(p);else {$('manage-category').onclick=()=>openMembers(current.value,'destination');$('add-from-category').onclick=()=>openProfile(null,current.value);if($('sync-category'))$('sync-category').onclick=()=>syncAll(group.filter(x=>x.role==='source'));}updateTimerElements();
$('show-import').onclick=()=>{const f=$('import-form');f.reset();if(p?.role==='source'){f.elements.account.value=p.name;f.elements.platform.value=['tiktok','instagram'].includes(p.platform)?p.platform:'other';}$('import-error').textContent='';$('import-dialog').showModal();};
if(!sourceOnly){$('destination').onchange=e=>{chosenDestination=Number(e.target.value);renderDashboard();};$('filter').value=filter;$('filter').onchange=e=>{filter=e.target.value;renderCards(visibleItems,sourceOnly);};$('user').oninput=e=>localStorage.setItem('lifeinvader-name',e.target.value.trim());$('pick').onclick=()=>pick(visibleItems);}
if(p){document.querySelector('#view .profile-hero')?.remove();loadAnalytics(p.id);loadQueue(p.id);}renderCards(visibleItems,sourceOnly);}
function renderSourceCategory(group){$('breadcrumb').innerHTML=`<button data-category-back>Categories</button> <span>/</span> ${esc(current.value)}`;const newTotal=group.reduce((sum,p)=>sum+(timerFor(p.id)?.new_count||0),0);$('view').innerHTML=`<div class="profile-hero"><div class="identity"><div class="category-avatar">#</div><div><div class="eyebrow">SOURCE CATEGORY</div><h1>${esc(current.value)}<span>.</span></h1><p>${group.length} sources</p></div></div><div class="hero-actions"><button class="button outline" id="manage-category-source">Manage sources</button><button class="button outline" id="add-category-source">＋ Add source</button><button class="button primary" id="sync-category">↻ Sync all</button></div></div><div class="source-category-stats"><div><small>SOURCES</small><strong>${group.length}</strong></div><div><small>DOWNLOADED VIDEOS</small><strong id="category-video-count">—</strong></div><div><small>NEW VIDEOS</small><strong id="category-new-count">${newTotal}</strong></div><div><small>AUTO SYNC</small><strong id="category-auto-count">${group.filter(p=>timerFor(p.id)?.enabled).length}</strong></div></div><div id="batch-status" class="batch-status" hidden></div><div class="section-heading group-heading"><div><div class="eyebrow">SOURCES IN THIS CATEGORY</div><h2>Source hubs</h2></div></div><div class="profiles-grid simple-grid">${group.map(sourceCard).join('')}</div>`;document.querySelector('[data-category-back]').onclick=()=>go('categories');$('manage-category-source').onclick=()=>openMembers(current.value,'source');$('add-category-source').onclick=()=>openProfile(null,current.value,'source');$('sync-category').onclick=()=>syncAll(group);attachProfiles();updateTimerElements();updateSourceCountElements();}
function renderCards(items,sourceOnly){const filtered=items.filter(i=>filter==='all'||i.category===filter);$('cards').innerHTML='';$('empty').hidden=!!filtered.length;
for(const item of filtered){const s=chosenDestination?status(item,chosenDestination):null;const article=document.createElement('article');article.className='content-card';article.id=`item-${item.id}`;const previews=item.files.map(f=>f.kind==='video'?`<video controls preload="metadata" src="${esc(f.url)}"></video>`:`<img loading="lazy" src="${esc(f.url)}" alt="${esc(f.name)}">`).join('');const original=safeUrl(item.source_url),post=safeUrl(s?.post_url);const label=!s?'':s.state==='available'?'Available to claim':s.state==='claimed'?`Claimed by ${s.claimed_by}`:`Reported posted by ${s.updated_by}`;const buttons=!s?'':s.state==='available'?'<button class="button dark" data-action="claim">Claim item</button>':s.state==='claimed'?'<button class="button primary" data-action="post">Record post</button><button class="button ghost" data-action="release">Release</button>':'<button class="button ghost" data-action="reset">Reopen</button>';
article.innerHTML=`<div class="preview ${item.files.length>1?'multiple':''}">${previews}</div><div class="card-body"><div class="card-top"><span class="pill">${esc(item.category==='review'?'Needs review':item.category==='before'?'Before launch':'At or after launch')}</span><small>${esc(platformLabel(item.platform))}</small></div><h3>@${esc(item.account.replace(/^@/,''))} · ${esc(item.post_id)}</h3><div class="meta">Original: ${esc(item.posted||'Unknown')} ${original?`· <a href="${esc(original)}" target="_blank" rel="noopener noreferrer">View source ↗</a>`:''}${item.caption?`<p>${esc(item.caption)}</p>`:''}<br>${item.files.map(f=>`<a href="${esc(f.url)}" download="${esc(f.name)}">Save ${esc(f.name)} ↓</a>`).join(' · ')}</div>${s?`<div class="status">${esc(label)} ${post?`· <a href="${esc(post)}" target="_blank" rel="noopener noreferrer">View post ↗</a>`:''}${s.caption?`<br>${esc(s.caption)}`:''}</div>`:''}<div class="card-actions">${buttons}<button class="button ghost" data-edit>Edit details</button></div></div>`;
article.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(item.id,b.dataset.action));article.querySelector('[data-edit]').onclick=()=>{editingItem=item.id;$('edit-account').value=item.account;$('edit-posted').value=item.posted;$('edit-url').value=item.source_url;$('edit-caption').value=item.caption;$('edit-error').textContent='';$('edit-dialog').showModal();};$('cards').append(article);}}
function timerFor(id){return timerInfo.schedules.find(s=>s.profile_id===Number(id));}
function formatRemaining(seconds){const s=Math.max(0,Math.ceil(seconds));if(s>=3600)return `${Math.floor(s/3600)}h ${String(Math.floor((s%3600)/60)).padStart(2,'0')}m`;if(s>=60)return `${Math.floor(s/60)}m ${String(s%60).padStart(2,'0')}s`;return `${s}s`;}
function updateTimerElements(){const now=Date.now()/1000;document.querySelectorAll('[data-timer]').forEach(el=>{const s=timerFor(el.dataset.timer);let text='Auto sync off',progress=0;if(s?.queue_state){text=s.queue_state==='running'?'Syncing…':'Queued';}else if(s?.last_state==='running'){text='Syncing…';}else if(s?.enabled&&s.next_run){const remaining=Math.max(0,s.next_run-now);text=`Next sync in ${formatRemaining(remaining)}`;progress=1-Math.min(1,remaining/s.interval_seconds);}else if(s?.enabled){text='Waiting to sync';}el.textContent=text;const ring=document.querySelector(`[data-ring="${el.dataset.timer}"]`);if(ring){ring.classList.toggle('scheduled',!!s?.enabled);ring.style.setProperty('--timer-progress',`${Math.max(0,Math.min(100,progress*100))}%`);}});
document.querySelectorAll('[data-new-count]').forEach(el=>{const n=timerFor(el.dataset.newCount)?.new_count||0;el.textContent=n?`${n} new`:'';el.hidden=!n;});const batch=$('batch-status');if(batch){const b=timerInfo.batch;batch.hidden=!b;if(b)batch.textContent=b.remaining?`Sync all: ${b.finished} of ${b.total} finished · ${b.remaining} queued or running${b.errors?` · ${b.errors} failed`:''}`:`Last sync all: ${b.finished} finished${b.errors?` · ${b.errors} failed`:''}`;}
document.querySelectorAll('[data-batch-label]').forEach(el=>{el.textContent=timerFor(el.dataset.batchLabel)?.include_in_batch===false?'Sync all off':'';});
if(current.type==='tag'&&$('category-new-count')){const group=data.profiles.filter(p=>p.role==='source'&&hasTag(p,current.value));$('category-new-count').textContent=group.reduce((sum,p)=>sum+(timerFor(p.id)?.new_count||0),0);$('category-auto-count').textContent=group.filter(p=>timerFor(p.id)?.enabled).length;}}
function updateSourceCountElements(){document.querySelectorAll('[data-source-count]').forEach(el=>{const c=sourceCounts.get(Number(el.dataset.sourceCount));if(c?.configured)el.textContent=el.classList.contains('quick-count')?`${c.videos} videos`:`${c.videos} videos · ${c.photos} photos`;});if(current.type==='tag'&&$('category-video-count')){const group=data.profiles.filter(p=>p.role==='source'&&hasTag(p,current.value));const counts=group.map(p=>sourceCounts.get(p.id));$('category-video-count').textContent=counts.every(c=>c?.configured)?counts.reduce((sum,c)=>sum+c.videos,0):'—';}}
async function loadSourceCounts(){const group=current.type==='sources'||current.type==='categories'&&categoryRole==='source'?data.profiles.filter(p=>p.role==='source'):current.type==='tag'&&categoryRole==='source'?data.profiles.filter(p=>p.role==='source'&&hasTag(p,current.value)):[];await Promise.all(group.map(async p=>{try{sourceCounts.set(p.id,await api(`/api/sources/${p.id}/summary`));}catch{sourceCounts.delete(p.id);}}));updateSourceCountElements();}
