function sourceStatus(run){if(!run)return 'Not synced yet';return ({running:'Sync in progress',finished:'Sync finished',error:'Sync finished with errors',interrupted:'Previous sync was interrupted'}[run.state]||run.state);}
function formatSyncLog(log){return (log||'').replace(/__LV_PROGRESS__\s*/g,'Download: ');}
function updateSyncProgress(run){const bar=$('sync-progress'),label=$('progress-label');if(!bar||!label)return;const log=run?.log||'';const photo=Math.max(log.lastIndexOf('Checking TikTok photo posts...'),log.lastIndexOf('Checking Instagram photo posts...'));const latest=log.lastIndexOf('__LV_PROGRESS__');const fragment=latest>=0?log.slice(latest).split(/[\r\n]/)[0]:'';const match=fragment.match(/__LV_PROGRESS__\s*(\d+(?:\.\d+)?)%/);if(run?.state==='finished'){bar.value=100;label.textContent='Sync finished';}else if(run?.state!=='running'){bar.removeAttribute('value');label.textContent=run?.state==='error'?'Stopped with errors':'Sync interrupted';}else if(photo>latest){bar.removeAttribute('value');label.textContent='Checking photo posts · total unknown';}else if(match){const value=Number(match[1]);if(Number.isFinite(value)&&value>=0&&value<=100){bar.value=value;label.textContent=`Video download: ${value.toFixed(1)}% · overall total unknown`;}else{bar.removeAttribute('value');label.textContent='Checking source · total unknown';}}else{bar.removeAttribute('value');label.textContent='Checking source · total unknown';}}
async function loadSource(id){try{const result=await api(`/api/sources/${id}`);if(current.type!=='source'||current.value!==id)return;sourceData=result;renderSource();if(result.last_run?.state==='running'&&!sourceTimer){sourceTimer=setInterval(()=>pollSource(id),1500);}}catch(err){if(current.type==='source'&&current.value===id){sourceData={error:err.message};renderSource();}}}
async function pollSource(id){try{const result=await api(`/api/sources/${id}/status`);if(current.type!=='source'||current.value!==id){clearInterval(sourceTimer);sourceTimer=null;return;}const run=result.last_run;if(sourceData)sourceData.last_run=run;if($('sync-status'))$('sync-status').textContent=sourceStatus(run);if($('sync-log'))$('sync-log').textContent=formatSyncLog(run?.log);updateSyncProgress(run);if(run?.state!=='running'){clearInterval(sourceTimer);sourceTimer=null;await loadSource(id);}}catch(err){clearInterval(sourceTimer);sourceTimer=null;if($('source-message'))$('source-message').textContent=err.message;}}
