function fileDate(f){
  let date,label;
  if(f.posted_date){date=new Date(f.posted_date+'T12:00:00');label='Posted';}
  else if(f.downloaded_at){date=new Date(f.downloaded_at*1000);label='Downloaded';}
  else if(f.created){date=new Date(f.created*1000);label='File created';}
  else return 'Date unknown';
  return Number.isNaN(date.getTime())?'Date unknown':`${label} ${date.toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric'})}`;
}
let masterVolume=Math.max(0,Math.min(1,Number(localStorage.getItem('lv-volume')??'0.7'))),masterMuted=localStorage.getItem('lv-muted')==='true';
function applyVolume(){document.querySelectorAll('video').forEach(v=>{v.volume=masterVolume;v.muted=masterMuted;});$('master-volume').value=Math.round(masterVolume*100);$('master-mute').textContent=masterMuted||masterVolume===0?'🔇':'🔊';$('master-mute').setAttribute('aria-label',masterMuted?'Unmute all videos':'Mute all videos');}
$('master-volume').oninput=e=>{masterVolume=Number(e.target.value)/100;masterMuted=false;localStorage.setItem('lv-volume',String(masterVolume));localStorage.setItem('lv-muted','false');applyVolume();};
$('master-mute').onclick=()=>{masterMuted=!masterMuted;localStorage.setItem('lv-muted',String(masterMuted));applyVolume();};
applyVolume();
function renderSourceFiles(){
  disposeGallery();if(!$('source-gallery'))return;
  const filtered=(sourceData?.files||[]).filter(f=>f.name.toLowerCase().includes(sourceSearch.toLowerCase()));
  const size=24,pages=Math.max(1,Math.ceil(filtered.length/size));sourcePage=Math.min(sourcePage,pages-1);
  const gallery=$('source-gallery');gallery.innerHTML='';
  for(const f of filtered.slice(sourcePage*size,(sourcePage+1)*size)){
    const url=current.type==='profile'?`/api/profiles/${current.value}/download-file?path=${encodeURIComponent(f.path)}`:`/api/sources/${current.value}/file?path=${encodeURIComponent(f.path)}`;
    const article=document.createElement('article');article.className=`source-file${f.is_new?' is-new':''}`;
    article.innerHTML=`<div class="source-preview">${f.kind==='video'?'<img class="source-poster" alt=""><span class="preview-loading">Preparing preview…</span><button class="preview-toggle" type="button" aria-label="Play video"><span>▶</span></button><span class="preview-error" hidden>Preview unavailable</span>':`<img loading="lazy" src="${esc(url)}" alt="${esc(f.name)}">`}${f.is_new?'<span class="new-label">NEW</span>':''}</div><div class="source-file-info"><strong title="${esc(f.name)}">${esc(f.name)}</strong><div class="file-date">${esc(fileDate(f))}</div><div><small>${f.kind==='video'?'VIDEO':'PHOTO'} · ${(f.size/1024/1024).toFixed(1)} MB</small><a href="${esc(url)}" download="${esc(f.name)}">Save ↓</a></div></div>`;
    gallery.append(article);const frame=article.querySelector('.source-preview');
    if(f.kind==='video'){
      const button=frame.querySelector('.preview-toggle'),img=frame.querySelector('img');
      const loadPreview=()=>{const key=JSON.stringify([sourceData.root,current.value,f.path,f.size,f.modified]);img.onload=()=>{frame.querySelector('.preview-loading').hidden=true;if(img.naturalWidth&&img.naturalHeight)frame.style.aspectRatio=`${img.naturalWidth}/${img.naturalHeight}`;};img.onerror=async()=>{img.onerror=null;const result=await LVPreviews.load(key,url,()=>article.isConnected);if(!article.isConnected)return;if(result?.blob){const blobUrl=URL.createObjectURL(result.blob);previewUrls.push(blobUrl);img.src=blobUrl;if(result.width&&result.height)frame.style.aspectRatio=`${result.width}/${result.height}`;}else{frame.querySelector('.preview-loading').hidden=true;frame.querySelector('.preview-error').hidden=false;}};img.src=current.type==='profile'?`/api/profiles/${current.value}/download-thumbnail?path=${encodeURIComponent(f.path)}&v=${f.size}-${f.modified}`:`/api/sources/${current.value}/thumbnail?path=${encodeURIComponent(f.path)}&v=${f.size}-${f.modified}`;};
      article._loadPreview=loadPreview;
      button.onclick=async()=>{let video=frame.querySelector('video');if(video&&!video.paused){video.pause();return;}
        if(activeVideo&&activeVideo!==video){activeVideo.pause();activeVideo.removeAttribute('src');activeVideo.load();activeVideo.remove();activeVideo=null;}
        if(!video){video=document.createElement('video');video.className='source-video';video.playsInline=true;video.preload='metadata';video.src=url;video.volume=masterVolume;video.muted=masterMuted;frame.insertBefore(video,button);video.onloadedmetadata=()=>{if(video.videoWidth&&video.videoHeight)frame.style.aspectRatio=`${video.videoWidth}/${video.videoHeight}`;};video.onplay=()=>{activeVideo=video;button.classList.add('playing');button.setAttribute('aria-label','Pause video');button.querySelector('span').textContent='Ⅱ';};video.onpause=()=>{button.classList.remove('playing');button.setAttribute('aria-label','Play video');button.querySelector('span').textContent='▶';};video.onerror=()=>{frame.querySelector('.preview-error').hidden=false;};}
        try{await video.play();}catch{frame.querySelector('.preview-error').hidden=false;}
      };
    }else{const img=frame.querySelector('img');img.onload=()=>{if(img.naturalWidth&&img.naturalHeight)frame.style.aspectRatio=`${img.naturalWidth}/${img.naturalHeight}`;};if(img.complete)img.onload();}
  }
  const videos=[...gallery.querySelectorAll('.source-file')].filter(a=>a._loadPreview);
  if('IntersectionObserver' in window){previewObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){previewObserver.unobserve(entry.target);entry.target._loadPreview();}}),{rootMargin:'500px'});videos.forEach(a=>previewObserver.observe(a));}else videos.forEach(a=>a._loadPreview());
  $('source-pages').innerHTML=filtered.length?`<button class="button ghost" id="source-prev" ${sourcePage===0?'disabled':''}>← Previous</button><span>${sourcePage+1} / ${pages} · ${filtered.length} files</span><button class="button ghost" id="source-next" ${sourcePage+1===pages?'disabled':''}>Next →</button>`:`<div class="empty source-empty"><h3>${sourceData?.error?'Unable to open this source.':sourceData?.configured?'No downloads found.':'Choose a source folder.'}</h3><p>${sourceData?.error?'Check the source link and platform.':sourceData?.configured?(current.type==='profile'?'Sync your posts or adjust your search.':'Sync this source or adjust your search.'):'Use Folder to select where the source folders are stored.'}</p></div>`;
  if(filtered.length){$('source-prev').onclick=()=>{sourcePage--;renderSourceFiles();};$('source-next').onclick=()=>{sourcePage++;renderSourceFiles();};}
}
function renderTopbar(){const p=['profile','source'].includes(current.type)?profileById(current.value):null;const identity=$('top-identity'),crumb=$('breadcrumb'),edit=$('top-edit'),open=$('top-open');identity.hidden=!p;crumb.hidden=!!p;edit.hidden=!p;open.hidden=!p||!safeUrl(p.url);if(p){identity.innerHTML=`${avatar(p)}<div><strong>@${esc(p.name)}</strong><small>${esc(platformLabel(p.platform))} · ${p.role==='source'?'Source':'Profile'}</small></div>`;edit.onclick=()=>openProfile(p);open.href=safeUrl(p.url);open.setAttribute('aria-label',`Open @${p.name} on ${platformLabel(p.platform)}`);}$('nav-back').disabled=navigationIndex===0;$('nav-forward').disabled=navigationIndex===navigationHistory.length-1;}
function render(){renderNav();if(current.type==='home'||current.type==='sources')renderHome();else if(current.type==='categories')renderCategories();else if(current.type==='source')renderSource();else renderDashboard();renderTopbar();}
function openProfile(p=null,tag='',role='destination'){editingProfile=p?.id||null;$('profile-form').reset();$('profile-title').textContent=p?(p.role==='source'?'Edit source':'Edit profile'):(role==='source'?'Add a source':'Add a profile');$('profile-url').value=p?.url||'';$('profile-name').value=p?.name||'';$('profile-platform').value=p?.platform||'tiktok';$('profile-role').value=p?.role||role;$('source-folder').value=p?.source_folder||'';$('source-folder-label').hidden=$('profile-role').value!=='source';$('profile-tags').value=p?p.tags.join(', '):tag;$('profile-platform').disabled=!!p;$('profile-role').disabled=!!p;$('profile-error').textContent='';$('profile-detected').textContent='TikTok, Instagram and YouTube account links are recognized automatically.';$('profile-options').open=!!p;$('profile-dialog').showModal();}
function pick(items){const candidates=items.filter(x=>status(x,chosenDestination)?.state==='available'&&(filter==='all'||x.category===filter));if(!candidates.length){$('library-message').textContent='No available items for this profile in this view.';return;}const r=new Uint32Array(1);crypto.getRandomValues(r);const item=candidates[r[0]%candidates.length];$('library-message').textContent=`Your pick: @${item.account.replace(/^@/,'')} · ${item.post_id}. Claim it to reserve it for this profile.`;document.getElementById(`item-${item.id}`)?.scrollIntoView({behavior:'smooth',block:'center'});}
async function action(id,what){$('library-message').textContent='';const user=person();if(!user){$('user')?.focus();$('library-message').textContent='Enter your name to attribute claims and updates.';return;}if(what==='post'){selectedPost={id,profile_id:chosenDestination,user};$('post-caption').value='';$('post-url').value='';$('post-error').textContent='';$('post-dialog').showModal();return;}try{await api(`/api/items/${id}/status`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({profile_id:chosenDestination,user,action:what})});await refresh();}catch(e){await refresh();$('library-message').textContent=e.message;}}
document.querySelector('[data-home]').onclick=()=>go('home');document.querySelector('[data-sources]').onclick=()=>go('sources');document.querySelector('[data-categories]').onclick=()=>go('categories');$('profile-role').onchange=()=>{$('source-folder-label').hidden=$('profile-role').value!=='source';};
$('nav-back').onclick=()=>moveHistory(-1);$('nav-forward').onclick=()=>moveHistory(1);
function setSidebar(open){document.querySelector('.layout').classList.toggle('sidebar-collapsed',!open);$('sidebar-toggle').setAttribute('aria-expanded',String(open));$('sidebar-toggle').setAttribute('aria-label',open?'Collapse sidebar to icons':'Expand sidebar');$('sidebar-toggle').title=open?'Collapse sidebar to icons':'Expand sidebar';localStorage.setItem('lifeinvader-sidebar-open',String(open));}
setSidebar(localStorage.getItem('lifeinvader-sidebar-open')!=='false');$('sidebar-toggle').onclick=()=>setSidebar($('sidebar-toggle').getAttribute('aria-expanded')!=='true');
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());
function identifyProfile(value){try{const u=new URL(value.trim()),host=u.hostname.toLowerCase(),bits=u.pathname.split('/').filter(Boolean);if(u.protocol!=='https:'||u.username||u.password)return null;const domain=d=>host===d||host.endsWith('.'+d);let platform='other',name='';if(domain('tiktok.com')){platform='tiktok';if(bits.length===1&&/^@[A-Za-z0-9._]+$/.test(bits[0]))name=bits[0].slice(1);}else if(domain('instagram.com')){platform='instagram';if(bits.length===1&&/^[A-Za-z0-9._]+$/.test(bits[0])&&!['p','reel','reels','stories','explore','accounts'].includes(bits[0].toLowerCase()))name=bits[0];}else if(domain('youtube.com')){platform='youtube';if(bits.length===1&&/^@[A-Za-z0-9._-]+$/.test(bits[0]))name=bits[0].slice(1);else if(bits.length===2&&['channel','c','user'].includes(bits[0])&&/^[A-Za-z0-9._-]+$/.test(bits[1]))name=bits[1];}return {platform,name};}catch{return null;}}
function detectProfile(){if(editingProfile)return;const result=identifyProfile($('profile-url').value);if(result?.name){$('profile-name').value=result.name;$('profile-platform').value=result.platform;$('profile-detected').textContent=`${platformLabel(result.platform)} · @${result.name} detected. Add a picture or category under More options.`;}else if($('profile-url').value.trim()){ $('profile-name').value='';$('profile-platform').value=result?.platform||'other';$('profile-detected').textContent='Account not recognized. Open More options to enter the name.';}else {$('profile-name').value='';$('profile-detected').textContent='TikTok, Instagram and YouTube account links are recognized automatically.';}}
$('profile-url').oninput=detectProfile;$('profile-url').onblur=()=>{if(!editingProfile&&$('profile-url').value.trim()&&!$('profile-name').value.trim())$('profile-options').open=true;};
$('profile-form').onsubmit=async e=>{e.preventDefault();if(!$('profile-name').value.trim()){$('profile-options').open=true;$('profile-error').textContent='Enter a name under More options.';return;}const body={url:$('profile-url').value.trim(),name:$('profile-name').value.trim(),platform:$('profile-platform').value,role:$('profile-role').value,source_folder:$('source-folder').value.trim(),tags:$('profile-tags').value.split(',').map(x=>x.trim()).filter(Boolean)};const button=e.submitter;button.disabled=true;try{const result=await api(editingProfile?`/api/profiles/${editingProfile}`:'/api/profiles',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const id=editingProfile||result.id;const photo=$('profile-photo').files[0];let warning='';if(photo){const form=new FormData();form.append('photo',photo);try{await api(`/api/profiles/${id}/photo`,{method:'POST',body:form});}catch(err){warning=` Source saved, but the picture could not be added: ${err.message}`;}}$('profile-dialog').close();await refresh();if(current.type==='source')await loadSource(current.value);$('notice').textContent=warning|| (editingProfile?'Saved.':'Added.');}catch(err){$('profile-error').textContent=err.message;}finally{button.disabled=false;}};
$('settings-button').onclick=()=>{$('cutoff').value=data.cutoff;$('settings-error').textContent='';$('settings-dialog').showModal();};
$('settings-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/settings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({cutoff:$('cutoff').value.trim()})});$('settings-dialog').close();await refresh();}catch(err){$('settings-error').textContent=err.message;}};
$('import-form').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;$('import-error').textContent='';try{await api('/api/items',{method:'POST',body:new FormData(e.target)});$('import-dialog').close();await refresh();$('notice').textContent='Content added to your library.';}catch(err){$('import-error').textContent=err.message;}finally{button.disabled=false;}};
$('post-form').onsubmit=async e=>{e.preventDefault();try{await api(`/api/items/${selectedPost.id}/status`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...selectedPost,action:'posted',caption:$('post-caption').value,post_url:$('post-url').value})});$('post-dialog').close();await refresh();}catch(err){$('post-error').textContent=err.message;}};
$('edit-form').onsubmit=async e=>{e.preventDefault();try{await api(`/api/items/${editingItem}/metadata`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({account:$('edit-account').value,posted:$('edit-posted').value,source_url:$('edit-url').value,caption:$('edit-caption').value})});$('edit-dialog').close();await refresh();}catch(err){$('edit-error').textContent=err.message;}};
refresh();
let analyticsChart=null;
async function loadAnalytics(id){
  const host=$('profile-analytics');if(!host)return;
  try{
    const records=await api(`/api/profiles/${id}/analytics`);if(current.type!=='profile'||current.value!==id||!$('profile-analytics'))return;
    const account=records.filter(r=>!r.post_id),posts=new Map();for(const r of records)if(r.post_id&&!posts.has(r.post_id))posts.set(r.post_id,r);
    const metrics=['followers','following','views','likes','comments','shares'];
    const metricCard=key=>{const samples=account.filter(r=>r[key]!==null&&r[key]!==undefined),latest=samples[0],previous=samples.find(r=>r.date<latest?.date),change=latest&&previous?latest[key]-previous[key]:null;return `<div><small>${esc(key.toUpperCase())}</small><strong>${latest?Number(latest[key]).toLocaleString():'—'}</strong><span>${latest?`As of ${esc(latest.date)}${change===null?'':` · ${change>=0?'+':''}${change.toLocaleString()} since ${esc(previous.date)}`}`:'No data yet'}</span></div>`;};
    const top=[...posts.values()].sort((a,b)=>(b.views??-1)-(a.views??-1)).slice(0,10);
    host.innerHTML=`<div class="section-heading analytics-heading"><div><div class="eyebrow">YOUR PERFORMANCE</div><h2>Analytics</h2><p>Saved on this computer · snapshots are entered or imported by you.</p></div><div class="analytics-actions"><button class="button ghost" id="analytics-template">CSV template</button><label class="button outline analytics-import">Import CSV<input id="analytics-csv" type="file" accept=".csv,text/csv" hidden></label><button class="button primary" id="analytics-add">＋ Record numbers</button></div></div><div id="analytics-message" role="status"></div><div class="dashboard-stats analytics-stats">${metrics.map(metricCard).join('')}</div><div class="analytics-panels"><div class="analytics-panel"><div class="analytics-panel-head"><h3>Account trend</h3><select id="analytics-metric" aria-label="Trend metric">${metrics.map(m=>`<option value="${m}">${m[0].toUpperCase()+m.slice(1)}</option>`).join('')}</select></div><div class="analytics-chart"><canvas id="analytics-chart" aria-label="Account metric trend" role="img"></canvas><p id="analytics-chart-empty">Record at least one account snapshot to see a trend.</p></div></div><div class="analytics-panel"><h3>Post performance</h3>${top.length?`<div class="analytics-table-wrap"><table class="analytics-table"><thead><tr><th>Post ID</th><th>Views</th><th>Likes</th><th>As of</th></tr></thead><tbody>${top.map(r=>`<tr><td>${esc(r.post_id)}</td><td>${r.views==null?'—':Number(r.views).toLocaleString()}</td><td>${r.likes==null?'—':Number(r.likes).toLocaleString()}</td><td>${esc(r.date)}</td></tr>`).join('')}</tbody></table></div>`:'<p>No post metrics yet. Add a post ID when recording numbers or importing CSV.</p>'}</div></div><p class="analytics-note">Metrics reflect the dates and values you provide. They are not live. Platform insights, publishing and automatic account connections are not yet available.</p>`;
    $('analytics-add').onclick=()=>{const f=$('analytics-form');f.reset();const now=new Date();f.elements.date.value=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-');$('analytics-error').textContent='';$('analytics-dialog').showModal();};
    $('analytics-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,body={date:f.elements.date.value,post_id:f.elements.post_id.value.trim()};for(const k of metrics)body[k]=f.elements[k].value===''?null:Number(f.elements[k].value);const button=e.submitter;button.disabled=true;try{await api(`/api/profiles/${id}/analytics`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});$('analytics-dialog').close();await loadAnalytics(id);}catch(err){$('analytics-error').textContent=err.message;}finally{button.disabled=false;}};
    $('analytics-template').onclick=()=>{const blob=new Blob(['date,post_id,followers,following,views,likes,comments,shares\r\n2026-11-18,,100,20,,,,\r\n2026-11-18,example-post,,,500,30,4,2\r\n'],{type:'text/csv'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='lifeinvader-analytics-template.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
    $('analytics-csv').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2*1024*1024)throw new Error('CSV must be 2 MB or smaller.');const result=await api(`/api/profiles/${id}/analytics/import`,{method:'POST',headers:{'Content-Type':'text/csv'},body:await file.text()});await loadAnalytics(id);if($('analytics-message'))$('analytics-message').textContent=`Imported ${result.imported} rows.`;}catch(err){$('analytics-message').textContent=err.message;}finally{e.target.value='';}};
    function draw(){const key=$('analytics-metric').value,points=account.filter(r=>r[key]!=null).slice().reverse();$('analytics-chart-empty').hidden=points.length>0;if(analyticsChart)analyticsChart.destroy();analyticsChart=null;if(points.length&&window.Chart){analyticsChart=new Chart($('analytics-chart'),{type:'line',data:{labels:points.map(r=>r.date),datasets:[{label:key,data:points.map(r=>r[key]),borderColor:'#ec65a4',backgroundColor:'rgba(236,101,164,.15)',tension:.2,pointRadius:3}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{y:{beginAtZero:false}}}});}}
    $('analytics-metric').onchange=draw;draw();
  }catch(err){if(current.type==='profile'&&current.value===id&&$('profile-analytics'))$('profile-analytics').innerHTML=`<p class="form-error">Analytics could not load: ${esc(err.message)}</p>`;}
}
let queueData=[],pickedSource=null,queueEdit=null;
async function loadQueue(id){
 try{const entries=await api(`/api/profiles/${id}/queue`);if(current.type!=='profile'||current.value!==id||!$('posting-queue'))return;queueData=entries;const active=entries.filter(x=>x.state==='queued'),history=entries.filter(x=>x.state!=='queued');
  const card=q=>`<article class="queue-card"><div class="queue-meta"><strong>${esc(q.title||q.post_id||q.path.split('/').pop())}</strong><small>${esc(platformLabel(q.platform))} · @${esc(q.source_name)} · ${q.posted_date?'Originally posted '+esc(q.posted_date):'Original date unknown'}${q.scheduled_for?' · Planned '+esc(q.scheduled_for.replace('T',' ')):''}</small>${q.description?`<p>${esc(q.description)}</p>`:''}${!q.available?'<small class="form-error">Original file unavailable. Check the selected source folder.</small>':''}</div><div class="queue-actions">${q.available?`<a class="button ghost" href="/api/sources/${q.source_id}/file?path=${encodeURIComponent(q.path)}" target="_blank">Open file</a>`:''}${safeUrl(q.channel_url)?`<a class="button ghost" href="${esc(safeUrl(q.channel_url))}" target="_blank" rel="noopener noreferrer">Source ↗</a>`:''}${safeUrl(q.original_url)?`<a class="button ghost" href="${esc(safeUrl(q.original_url))}" target="_blank" rel="noopener noreferrer">Original post ↗</a>`:''}<button class="button ghost" data-copy="${q.id}">Copy text</button><button class="button outline" data-queue-edit="${q.id}">${q.state==='queued'?'Update status':esc(q.state)}</button></div></article>`;
  $('posting-queue').innerHTML=`<div class="section-heading"><div><div class="eyebrow">YOUR NEXT POSTS</div><h2>Posting queue <small>${active.length}</small></h2><p>Items stay here until you record their status. Planned times do not post automatically.</p></div><button class="button primary" id="queue-pick">✳ Pick from sources</button></div><div id="queue-message" role="status"></div>${active.length?active.map(card).join(''):'<div class="queue-empty">Your queue is empty. Pick a downloaded post from your sources.</div>'}${history.length?`<details class="queue-history"><summary>Recorded posts (${history.length})</summary>${history.map(card).join('')}</details>`:''}`;
  $('queue-pick').onclick=()=>openPicker(id);$('posting-queue').querySelectorAll('[data-copy]').forEach(button=>button.onclick=async()=>{const q=entries.find(x=>x.id===Number(button.dataset.copy));try{await navigator.clipboard.writeText([q.title,q.description,q.original_url,q.channel_url].filter(Boolean).join('\n\n'));$('queue-message').textContent='Source details copied.';}catch{$('queue-message').textContent='Clipboard unavailable. Select and copy the text instead.';}});
  $('posting-queue').querySelectorAll('[data-queue-edit]').forEach(button=>button.onclick=()=>{const q=entries.find(x=>x.id===Number(button.dataset.queueEdit));queueEdit=q;$('queue-state').value=q.state;$('queue-caption').value=q.caption;$('queue-post-url').value=q.post_url;$('queue-scheduled').value=q.scheduled_for;$('queue-error').textContent='';$('queue-dialog').showModal();});
  $('queue-form').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{await api(`/api/profiles/${id}/queue/${queueEdit.id}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({state:$('queue-state').value,caption:$('queue-caption').value,post_url:$('queue-post-url').value.trim(),scheduled_for:$('queue-scheduled').value})});$('queue-dialog').close();await loadQueue(id);}catch(err){$('queue-error').textContent=err.message;}finally{button.disabled=false;}};
 }catch(e){if(current.type==='profile'&&current.value===id&&$('posting-queue'))$('posting-queue').innerHTML=`<p class="form-error">Queue could not load: ${esc(e.message)}</p>`;}
}
function openPicker(id){
 const sources=data.profiles.filter(p=>p.role==='source');$('picker-form').reset();$('picker-category').innerHTML='<option value="">All categories</option>'+allTags('source').map(t=>`<option value="${esc(t)}">${esc(t)}</option>`).join('');$('picker-source').innerHTML='<option value="">All sources</option>'+sources.map(p=>`<option value="${p.id}">${esc(platformLabel(p.platform))} · @${esc(p.name)}</option>`).join('');$('picker-result').textContent='Choose filters, then pick a post.';$('picker-error').textContent='';$('picker-queue').disabled=true;pickedSource=null;$('picker-dialog').showModal();
 $('picker-random').onclick=async()=>{const button=$('picker-random');button.disabled=true;$('picker-error').textContent='';$('picker-result').textContent='Looking through downloaded posts…';try{const category=$('picker-category').value,selected=$('picker-source').value,from=$('picker-from').value,to=$('picker-to').value,query=$('picker-search').value.trim().toLowerCase(),unknown=$('picker-unknown').checked;if(from&&to&&from>to)throw new Error('The start date must be before the end date.');const group=sources.filter(p=>(!selected||p.id===Number(selected))&&(!category||hasTag(p,category)));const results=await Promise.all(group.map(async p=>{try{const r=await api(`/api/sources/${p.id}`);return {p,files:r.files||[],configured:r.configured};}catch{return {p,files:[],error:true};}}));let candidates=[];for(const {p,files} of results)for(const f of files){if(f.kind!=='video')continue;const date=f.posted_date||'';if((from||to)&&!date&&!unknown)continue;if(date&&((from&&date<from)||(to&&date>to)))continue;if(query&&!`${f.title||f.name} ${f.description||''}`.toLowerCase().includes(query))continue;if(queueData.some(q=>q.platform===p.platform&&(f.post_id?q.post_id===f.post_id:q.source_id===p.id&&q.path===f.path)))continue;candidates.push({p,f});}const unique=new Map();for(const c of candidates){const key=c.f.post_id?`${c.p.platform}:${c.f.post_id}`:`${c.p.id}:${c.f.path}`;if(!unique.has(key))unique.set(key,c);}candidates=[...unique.values()];if(!candidates.length){pickedSource=null;$('picker-queue').disabled=true;$('picker-result').textContent='No eligible downloaded videos match. Check source folders, filters and recorded posts.';if(results.some(r=>r.error||!r.configured))$('picker-error').textContent='Some sources could not be opened.';return;}const random=new Uint32Array(1);crypto.getRandomValues(random);pickedSource=candidates[random[0]%candidates.length];const {p,f}=pickedSource;$('picker-result').innerHTML=`<strong>${esc(f.title||f.name)}</strong><p>@${esc(p.name)} · ${f.posted_date?'Originally posted '+esc(f.posted_date):'Original date unknown'}</p>${f.description?`<p>${esc(f.description)}</p>`:''}<small>${candidates.length} matching posts</small>`;$('picker-queue').disabled=false;if(results.some(r=>r.error||!r.configured))$('picker-error').textContent='Some sources could not be opened.';}catch(e){$('picker-error').textContent=e.message;}finally{button.disabled=false;}};
 $('picker-form').onsubmit=async e=>{e.preventDefault();if(!pickedSource)return;const button=e.submitter;button.disabled=true;try{await api(`/api/profiles/${id}/queue`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({source_id:pickedSource.p.id,path:pickedSource.f.path,scheduled_for:$('picker-scheduled').value})});$('picker-dialog').close();await loadQueue(id);}catch(err){$('picker-error').textContent=err.message;button.disabled=false;}};
}
